    r.submission_url = byPath(d, /(AccessToolsURI|EndpointID)$/, NOT_OBJECT).find(t => /^https?:\/\//i.test(t)) || null;
    r.lots = [];
    for (const [k, v] of walk(d)) if (k === 'ProcurementProjectLot' && v && typeof v === 'object' && !Array.isArray(v)) {
