    else if (u.startsWith('?')) u = `${b.protocol}//${b.host}${b.pathname}${u}`;
    else if (u.startsWith('#') || u === '') u = `${b.protocol}//${b.host}${b.pathname}${b.search}${u}`;
    else u = `${b.protocol}//${b.host}${b.pathname.replace(/[^/]*$/, '')}${u}`;
