// ---------- pass 1: normalise ----------
const all = $input.all().map(i => i.json);
const passthrough = all.filter(t => t._type);                 // source errors + run marker
const ts = all.filter(t => !t._type && t.title);
for (const t of ts) {
  t.flags = t.flags || [];
  for (const f of ['publication_date', 'deadline', 'rectified_deadline']) {
    const raw = t[f], p = (f === 'rectified_deadline' ? parseNewDeadline : parseDate)(raw, t.date_order);
    if (raw && p.unreadable) t.flags.push(`${f}_unreadable:${String(raw).slice(0, 40)}`);
    t[`${f}_raw`] = raw ?? null; t[f] = p.value;
  }
  t.title_key = titleKey(t);
  t.buyer_key = normKey(t.buyer && t.buyer.name) || `unknown:${t.tender_id}`;   // unknown buyers are never grouped together
  t.pair_key = `${t.title_key}|${t.buyer_key}`;
  if (t.source_type === 'api' && excl.length) {                // broad pre-filter, API records only (a URL source is the user's own choice)
    const text = normKey(`${t.title} ${t.market_type || ''} ${(t.categories || []).join(' ')} ${t.body_text || ''}`);
    const ex = excl.find(k => has(text, k));
    if (ex && !kws.some(k => has(text, k))) t.drop_reason = `prefilter: "${ex}" and no company keyword`;
  }
}

// ---------- pass 2: superseded notices and rectifications ----------
const byExt = new Map(ts.filter(t => t.external_id).map(t => [`${t.source}|${t.external_id}`, t]));
const byPair = {}; for (const t of ts) (byPair[t.pair_key] ||= []).push(t);
// oldest rectification first, so the newest new deadline wins; originals are taken from the input types (never from a
// rectification promoted below)
const rects = ts.filter(t => t.notice_type === 'rectification').sort((a, b) => (a.publication_date || '').localeCompare(b.publication_date || ''));
const isOriginal = o => !['rectification', 'award', 'cancelled'].includes(o.notice_type) && !o.flags.includes('rectification_without_original');
for (const r of rects) {
  const linked = (r.supersedes || []).map(id => byExt.get(`${r.source}|${id}`)).filter(Boolean);
  const originals = (linked.length ? linked : byPair[r.pair_key] || []).filter(o => o !== r && isOriginal(o));
  if (originals.length) {
    for (const o of originals) if (r.rectified_deadline) { o.rectified_deadline = r.rectified_deadline; o.flags.push(`deadline_rectified_by:${r.canonical_id}`); }
    r.drop_reason ||= `rectification merged into ${originals[0].canonical_id}`;
  } else if (r.rectified_deadline || r.deadline || r.flags.some(f => /^(rectified_)?deadline_unreadable/.test(f))) {   // the rectification is the tender
    r.notice_type = 'open'; r.flags.push('rectification_without_original');      // (a new deadline it states but no one can read: kept, deadline_unknown_kept)
  } else r.drop_reason = 'rectification without its original nor a new deadline';                                         // nothing to evaluate
}
for (const t of ts.filter(t => (t.supersedes || []).length && t.notice_type !== 'rectification')) {   // a newer version replaces older ones
  for (const id of t.supersedes) {
    const o = byExt.get(`${t.source}|${id}`);
    if (o && o !== t && !o.drop_reason && o.title_key === t.title_key && (o.publication_date || '') <= (t.publication_date || '')) o.drop_reason = `superseded by ${t.canonical_id}`;
  }
}

// ---------- pass 3: awards, cancellations, expiry ----------
for (const t of ts) {
  if (t.drop_reason) continue;
  // an award notice has no bid deadline: a date it carries is the award or the contract's (dropped row of the export, never a deadline)
  t.effective_deadline = t.notice_type === 'award' ? null : t.rectified_deadline || t.deadline || null;
  if (t.notice_type === 'award') { t.drop_reason = 'award notice'; continue; }
  if (t.notice_type === 'cancelled') { t.drop_reason = 'cancelled notice'; continue; }
  if (t.notice_type === 'other') t.flags.push('notice_type_other');
  if (t.effective_deadline) {
    if (t.effective_deadline < today) t.drop_reason = `expired (deadline ${t.effective_deadline})`;
    else t.days_left = daysBetween(today, t.effective_deadline);
  } else if (t.flags.some(f => /^(rectified_)?deadline_unreadable/.test(f))) t.flags.push('deadline_unknown_kept');
  else if (t.publication_date && daysBetween(t.publication_date, today) > cfg.limits.staleNoDeadlineDays) t.drop_reason = `expired (no deadline, published ${t.publication_date})`;
  else t.flags.push('no_deadline');
}

// ---------- pass 3b: same reference number + same buyer = same notice ----------
// e.g. "Consultation N°28/2026" reached twice on a site (a category page and the post itself): the copy without a deadline
// takes its twin's fate (duplicate of a kept one, or expired with it). A number is a reference only after its marker (n°, no, num,
// réf, AO, رقم, عدد: URL5's refOf): a period "01/2026 à 12/2026" in two titles of one buyer is no shared reference
const refOf = t => { const m = String(t.title || '').replace(/[٠-٩]/g, c => c.charCodeAt(0) - 0x660).match(/(?:\bn\s?[°º]|\bno\.?|\bnum(?:[ée]ro)?|\br[ée]f(?:[ée]rence)?|\bao[ino]?|رقم|عدد)\s*[.:]?\s*(\d{1,5})\s*\/\s*((?:19|20)\d{2})(?![\d/])/i); return m ? `${+m[1]}/${m[2]}` : null; };
const sameBuyer = (a, b) => !(a.buyer && a.buyer.name) || !(b.buyer && b.buyer.name) || nameSim(a.buyer.name, b.buyer.name) >= 0.8;
const byRef = {};
for (const t of ts) { t.reference = refOf(t); if (t.reference) (byRef[t.reference] ||= []).push(t); }
for (const group of Object.values(byRef)) {
  if (group.length < 2) continue;
  for (const t of group.filter(x => !x.effective_deadline && !x.drop_reason)) {
    const twin = group.find(o => o !== t && o.effective_deadline && sameBuyer(o, t));
    if (!twin) continue;
    t.flags.push(`same_reference_as:${twin.tender_id}`);
    t.drop_reason = twin.drop_reason ? `duplicate of ${twin.tender_id} (${twin.drop_reason})` : `duplicate of ${twin.tender_id} (same reference ${t.reference})`;
  }
}

// ---------- pass 4: duplicates (canonical id, then title + buyer), relaunches, previous runs ----------
const richness = t => (t.body_text || '').length + (t.source_type === 'api' ? 1e6 : 0);
const seen = new Map();
for (const t of ts.filter(t => !t.drop_reason).sort((a, b) => richness(b) - richness(a))) {
  const dupe = seen.get(`c:${t.canonical_id}`) || seen.get(`p:${t.pair_key}`);
  if (dupe) {
    const sameDeadline = !dupe.effective_deadline || !t.effective_deadline || dupe.effective_deadline === t.effective_deadline;
    if (dupe.canonical_id === t.canonical_id || sameDeadline) {
      t.drop_reason = dupe.drop_reason ? `duplicate of ${dupe.tender_id} (${dupe.drop_reason})` : `duplicate of ${dupe.tender_id}`;
      (dupe.also_seen_in ||= []).push({ source: t.source, url: t.source_url });
      continue;
    }
    const [older, newer] = [dupe, t].sort((a, b) => (a.publication_date || '').localeCompare(b.publication_date || ''));
    newer.relaunch_of = older.tender_id;                       // same title + buyer, new deadline: both kept
  }
  seen.set(`c:${t.canonical_id}`, t); seen.set(`p:${t.pair_key}`, t);   // registered first: a later copy of a known tender is a duplicate
  const updates = (t.supersedes || []).some(id => known.has(`${t.source}:${id}`));
  if (known.has(t.canonical_id)) {
    t.flags.push('seen_in_previous_run');
    // a known tender whose deadline moved in this run is exported again (its sheet row gets the new deadline)
    if (t.flags.some(f => f.startsWith('deadline_rectified_by:'))) t.flags.push('deadline_updated_since_export');
    else if (cfg.limits.skipKnown) t.drop_reason = 'already exported by a previous run';
  } else if (updates) t.flags.push('update_of_previous_run');          // a new version of a notice exported before
  else if (known.has(t.pair_key)) {
    // same title + buyer as an exported tender: with the deadline it was exported with (02 pair_deadlines), the same notice reached
    // under another URL (a site echoing the Config search in its links, a mirror page); a relaunch only when the deadline differs,
    // or is unknown on either side (nothing proves it is the same notice: kept)
    if (t.effective_deadline && (pairDeadlines[t.pair_key] || []).includes(t.effective_deadline)) {
      t.flags.push('seen_in_previous_run');
      if (cfg.limits.skipKnown) t.drop_reason = 'already exported by a previous run (same title, buyer and deadline)';
    } else { t.flags.push('relaunch_of_previous_run'); t.relaunch_of ||= 'previous_run'; }
  }
}

// ---------- pass 5: buyer groups ----------
const groups = {};
for (const t of ts.filter(t => !t.drop_reason)) (groups[t.buyer_key] ||= []).push(t.tender_id);
for (const t of ts) {
  t.buyer_id = 'B' + fnv(t.buyer_key);
  t.buyer_group_size = (groups[t.buyer_key] || []).length;
  t.status = t.drop_reason ? 'dropped' : 'kept';
}
return [...ts, ...passthrough].map(json => ({ json }));

// Build Analysis Prompt. ONE LLM call per kept tender, BEFORE any expensive research: closed labels (type + fit) against the
// company profile, one verbatim quote as proof, and - only when the fit is high or medium - the requirements written in the text.
// Tender types come from Config (company.tenderTypes). Dropped tenders, source errors and the run marker get _run = false.
// ---- shared helpers ----
const INVIS = /[\u200B-\u200F\u202A-\u202E\u2060-\u2064\u061C\uFEFF\u00AD]/g;
// script-agnostic folding: lowercase, no accents / Arabic diacritics / tatweel, unified alef / ya / ta marbuta,
// Arabic-Indic digits -> ASCII, punctuation -> space
const fold = s => String(s ?? '').replace(INVIS, '').replace(/[\u00A0\u202F\u2007]/g, ' ').toLowerCase().normalize('NFKD')
  .replace(/[\u0300-\u036F\u064B-\u065F\u0670ـ]/g, '')
  .replace(/[آأإ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x660)).replace(/[۰-۹]/g, c => String(c.charCodeAt(0) - 0x6F0))
  .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const toks = s => fold(s).split(' ').filter(t => t.length > 1);
// ---- end helpers ----
const cfg = $('00 - Config').first().json;
const cp = cfg.company;
const types = Object.entries(cp.tenderTypes || {});
const system = 'You are a bid manager. You read ONE public tender and judge it against ONE company profile. Answer with ONE JSON object only.';
const company = `COMPANY: ${cp.name}
SERVICES:
${cp.services.map((s, k) => `${k + 1}. ${s}`).join('\n')}
TECHNOLOGIES: ${cp.technologies.join(', ')}
TENDER TYPES THE COMPANY BIDS ON: ${types.filter(([, t]) => t.bid).map(([k]) => k).join(', ') || '-'}
DOES NOT DO: ${[...types.filter(([, t]) => !t.bid).map(([k]) => k), ...(cp.exclusions || [])].join(', ') || '-'}`;
const typeList = [...types.map(([k, t]) => `${k} (${t.desc})`), 'other'].join(', ');
const RAG_LANG = (cfg.rag && cfg.rag.language) || 'English';   // the language of the RAG knowledge base (Config rag.language)
// CPV divisions (the 2 first digits of a CPV code): a bare "33696500" means nothing to a model, "medical equipment" does
const CPV_DIV = { '03': 'agriculture, farming products', '09': 'fuels, energy', 14: 'mining products', 15: 'food, beverages', 16: 'agricultural machinery',
  18: 'clothing, footwear', 19: 'leather, textiles, plastics', 22: 'printed matter, books', 24: 'chemical products', 30: 'computers and office equipment',
  31: 'electrical machinery, lighting', 32: 'radio, TV, telecom equipment', 33: 'medical equipment, pharmaceuticals', 34: 'vehicles, transport equipment',
  35: 'security, defence equipment', 37: 'musical, sports goods, toys', 38: 'laboratory, optical, precision equipment', 39: 'furniture, household goods',
  41: 'water', 42: 'industrial machinery', 43: 'mining, construction machinery', 44: 'construction materials', 45: 'construction works',
  48: 'software packages, information systems', 50: 'repair and maintenance services', 51: 'installation services', 55: 'hotel, restaurant, catering',
  60: 'transport services', 63: 'transport support, travel', 64: 'postal and telecom services', 65: 'public utilities', 66: 'financial, insurance services',
  70: 'real estate', 71: 'architecture, engineering, inspection', 72: 'IT services: consulting, software development, Internet, support',
  73: 'research and development', 75: 'public administration, defence, social security', 76: 'oil and gas services', 77: 'agricultural, forestry, horticultural services',
  79: 'business services: legal, marketing, consulting, recruitment, printing, security', 80: 'education and training', 85: 'health and social work',
  90: 'sewage, refuse, cleaning, environmental services', 92: 'recreational, cultural, sporting services', 98: 'other community, personal services' };
const cpvText = cpv => (cpv || []).map(c => `${c}${CPV_DIV[String(c).slice(0, 2)] ? ` (${CPV_DIV[String(c).slice(0, 2)]})` : ''}`).join(', ');
// a portal page often ends with OTHER notices ("## Appels d'offres à proximité", "## Related tenders", "## مناقصات أخرى"): such a
// section is cut up to the next heading of the same or a higher level (its own sub-headings, "### Notice A", are other notices
// too), so a word of another notice ("... en gîte communal et touristique" on an LLM-agents notice) can never become this
// tender's sector, quote or requirement
const othersHeading = line => /^#{1,6}\s/.test(line) && /(appels? d.offres?|\bavis\b|annonces?|march[ée]s\b|consultations|tenders|notices|opportunit|مناقص|طلبات? عروض)/i.test(line)
  && /(proximit|similaire|m[êe]me (source|acheteur|r[ée]gion|secteur|cat[ée]gorie)|connexe|r[ée]cent|derni[eè]r|autres|other|related|similar|nearby|recent|latest|see also|voir aussi|أخرى|مشابه|ذات صلة)/i.test(line);
const cutOthers = s => { let skip = 0;   // the level (number of #) of the others-heading being cut, 0 = keep
  return String(s || '').split('\n').filter(line => { const h = /^(#{1,6})\s/.exec(line); if (h && (!skip || h[1].length <= skip)) skip = othersHeading(line) ? h[1].length : 0; return !skip; }).join('\n'); };
return $input.all().map(({ json: t }) => {
  if (t._type || t.status !== 'kept') return { json: { ...t, _run: false } };
  // the source text only: API body_text already holds title + description + lots; on the URL lane the page itself (never the
  // extract LLM's description, so a fact it invented can not become a "verbatim" quote)
  const text = cutOthers(t.source_type === 'url' ? [t.title, t.body_text].filter(Boolean).join('\n') : t.body_text || [t.title, t.description].filter(Boolean).join('\n')).slice(0, cfg.limits.analysisMaxChars);
  const titleOnly = toks(text).length - toks(t.title).length < 40;
  const user = `${company}

TENDER
Title: ${t.title}
Buyer: ${(t.buyer && t.buyer.name) || '-'}
CPV: ${cpvText(t.cpv) || '-'}
TENDER TEXT:
"""${text}"""

Answer in this order:
1. tender_type = the MAIN object of the tender, one of: ${typeList}.
2. fit: compare the MAIN deliverable with the SERVICES list above. high = the main deliverable is one of these services; medium = an important part (a lot, a module) is; low = only loosely related; none = not the company's business. Supplying equipment or reselling / maintaining a specific vendor's product is "low" or "none" unless the SERVICES list says the company does it; so is a study, a survey or a supply of data or statistics (the deliverable is a report or a dataset, not software); so is running or supporting IT in general (outsourced IT operations or IT department, maintenance of IT equipment, servers or networks, user helpdesk) and an audit or a compliance assessment. Being about IT is not enough: the deliverable itself must be one of the SERVICES.
3. reason: ONE short sentence in quotes (a text, never a list), only with facts written in the TENDER TEXT, even when fit is none.
   services: the NUMBERS (1 to ${cp.services.length}) of each service of the SERVICES list the TENDER TEXT asks for (not the whole list), e.g. [2] or [1, 5]; [] if none.
4. quote: ONE sentence (5 to 30 words) copied EXACTLY from the TENDER TEXT that supports your answer.
5. sector: the buyer's sector as this tender states it (title, buyer, object), exactly one of: ${(cfg.rag.sectors || []).join(', ') || 'public sector, health, education'}; or null if none fits. Other notices listed on the same page do not count.
6. requirements: ONLY when fit is high or medium, every requirement the bidder must meet that is WRITTEN in the TENDER TEXT, else []. Each sentence with an obligation or a wish (doit, devra, obligatoire, exigé, au moins, souhaité, must, shall, required, preferably, يجب...) about the solution, the team or the references gives at least one item; administrative documents (forms, tax or insurance certificates, signatures) are not requirements.${titleOnly ? '\n   This text is only a title: requirements must be [].' : ''}
   category: technical (technologies, functions, deliverables, standards, hosting, security), team (roles, profiles, qualifications,
   staff, headcount), experience (references, similar projects, years of experience, certifications). Look for team and experience
   requirements too, not only technical ones.
   text: ONE requirement only, short (5 to 20 words), TRANSLATED into ${RAG_LANG}, never the original sentence (it is matched against the
   company's ${RAG_LANG} documents: CVs, past projects, tech stack). A sentence that lists several requirements becomes several items
   (they may share the same quote).
   skill: the SAME requirement as a short line of 2 to 8 words in ${RAG_LANG}, the way a CV or a tech stack writes it: name the
   technology, role, certification or kind of project, keep the count, drop "the system must", "the bidder shall", "provide".
   Forms, each <...> filled with what the quote says: "<technology>", "<technology> or <technology>", "Minimum <n> senior
   <role>s", "1 <role> <certification> certified", "<n>+ <kind of project> projects", "<standard> certification".
   A technology is written by its name only, never followed by a generic word (interface, server, layer, exposure, development,
   hosting): "<technology>", not "<technology> interface". A role is the job title a CV uses, not a word-for-word translation.
   Use only what the quote states: never add a kind of system (chatbot, mobile app, website, dashboard...), a technology, a sector
   or one of the SERVICES that it does not name, and never narrow it ("public or private clients" stays both).
   Write numbers as digits (3, not three). quote: the words of the TENDER TEXT that state it, copied EXACTLY (original language).
   Never invent years of experience, certifications or standards.
7. timeline: the duration or execution period of the contract written in the text, with its unit as written ("<n> mois", "<n> years"; not the publication date, not the bid deadline, not a start date), else null. No duration in the text = null.
{"tender_type":"...","fit":"...","reason":"...","services":[],"quote":"...","sector":null,"requirements":[{"category":"...","text":"...","skill":"...","quote":"..."}],"timeline":null}`;
  return { json: { ...t, _run: true, _title_only: titleOnly, _text: text, _sys: system, _usr: user } };
});

// Verify Analysis. Code checks what the LLM claims: the quote must be in the tender text (else fit goes down one level),
// a tender type the company does not bid on (Config company.tenderTypes, bid: false) is forced to "none", survivors = high / medium.
// Requirements are kept only when their quote is in the text and every number of their paraphrase is in that quote.
// rag_text = the short skill line sent to the RAG (its rules read "PostgreSQL", "3 senior developers"; long sentences fall to its
// reranker and come back missing): kept when 1 to 10 words and its numbers, names, sectors, kinds of system (or the title's) and
// most of its words are in the quote too, else the text is sent (checked the same way, and never the untranslated quote itself).
// A generic word next to a technology ("Angular interface") is dropped unless part of its name ("SQL Server"), a company SERVICES
// phrase must be a phrase of the quote.
// The sector must be written in the tender, the timeline must be a duration the text states (a bare number gets its unit from it),
// services given by name are mapped back to Config company.services (numbers only written in the reason, or a list of every service,
// are checked against the text), and obligation sentences that no kept requirement quotes (form fields and procedure apart, once
// each) are listed (requirements.uncovered).
// Output: ALL items (dropped tenders, errors and the run marker too) so the line always reaches Run Summary.
// ---- shared helpers ----
const INVIS = /[\u200B-\u200F\u202A-\u202E\u2060-\u2064\u061C\uFEFF\u00AD]/g;
// script-agnostic folding: lowercase, no accents / Arabic diacritics / tatweel, unified alef / ya / ta marbuta,
// Arabic-Indic digits -> ASCII, punctuation -> space
const fold = s => String(s ?? '').replace(INVIS, '').replace(/[\u00A0\u202F\u2007]/g, ' ').toLowerCase().normalize('NFKD')
  .replace(/[\u0300-\u036F\u064B-\u065F\u0670ـ]/g, '')
  .replace(/[آأإ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x660)).replace(/[۰-۹]/g, c => String(c.charCodeAt(0) - 0x6F0))
  .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
// a quote is "verbatim" if its folded form is inside the folded text, or (weak-model tolerance) an in-order token
// window of the text covers >= 85% of the quote's tokens AND every number of the quote ("3 ans" quoted as "5 ans" fails).
const quoteInText = (quote, text, min = 0.85) => {
  const q = fold(quote), t = fold(text);
  if (!q || q.split(' ').length < 3) return false;
  if ((' ' + t + ' ').includes(' ' + q + ' ')) return true;
  // words glued or split by the page itself ("intelligenceartificielle"): compare without spaces; a number at either end
  // must not continue into a longer number (inside the quote, numbers stay anchored by the letters around them)
  const qs = q.replace(/ /g, ''), ts = t.replace(/ /g, ''), at = ts.indexOf(qs);
  if (at >= 0 && !(/\d/.test(qs[0]) && /\d/.test(ts[at - 1] || '')) && !(/\d/.test(qs[qs.length - 1]) && /\d/.test(ts[at + qs.length] || ''))) return true;
  const Q = q.split(' '), T = t.split(' ');
  // anchors that must be matched exactly: numbers in digits or in words ("trois références" quoted for "deux" fails)
  const NUMW = /^(deux|trois|quatre|cinq|six|sept|huit|neuf|dix|onze|douze|quinze|vingt|trente|quarante|cinquante|cent|mille|two|three|four|five|seven|eight|nine|ten|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand)$/;
  // a negation the window skips (text "ne comprend PAS", quote "comprend") or that the quote adds, changes the meaning
  const NEG = /^(ne|n|pas|non|sans|aucun|aucune|jamais|ni|not|no|never|without|nor|لا|ليس|غير|دون|لن|لم)$/;
  const anchors = Q.map((x, k) => (/\d/.test(x) || NUMW.test(x) ? k : -1)).filter(k => k >= 0);
  for (let i = 0; i < T.length; i++) {
    const start = [0, 1, 2].find(k => Q[k] !== undefined && T[i] === Q[k]);   // the first words may differ a little
    if (start === undefined) continue;
    let qi = start, last = i;
    const hits = new Set(), skipped = [];
    for (let ti = i; qi < Q.length && ti < T.length && ti - i < Q.length * 1.3 + 3; ti++) {
      if (T[ti] === Q[qi]) { hits.add(qi); qi++; last = ti; } else if (T[ti] === Q[qi + 1]) { hits.add(qi + 1); qi += 2; last = ti; } else skipped.push(ti);
    }
    if (hits.size / Q.length < min || !anchors.every(k => hits.has(k))) continue;
    if (skipped.some(ti => ti <= last && NEG.test(T[ti])) || Q.some((x, k) => !hits.has(k) && NEG.test(x))) continue;
    return true;
  }
  return false;
};
// LLM answer (Basic LLM Chain {text} | Agent {output} | error item) -> {ok, value, errors, raw}.
