  const evNums = new Set([...(fold(evText.replace(PHONE_LIKE, ' ')).match(/\d+/g) || []), ...(evText.match(/\b(19|20)\d{2}\b/g) || [])]);
  let a = parseAnswer(r, schema, fallback);
