  if (byForm && ['private_company', 'other', 'unknown'].includes(buyer_type)) {
    if (v.buyer_type !== 'unknown') checks.push(`buyer type ${byForm} from the registry legal form ${reg.nature} (agent said ${v.buyer_type})`);
