  }
  out.push({ json: { ...b, _run: undefined, research_status, enrichment_status: n >= 2 ? 'enriched' : n === 1 ? 'partial' : 'none', facts,
    profile: {
      buyer_type, size_hint: sizeByStaff || (sizeEvidence ? v.size_hint : 'unknown'), summary,
